package com.nihongo.staff.controller;
import com.nihongo.staff.repository.*;import com.nihongo.security.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.http.*;import org.springframework.data.domain.PageRequest;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/staff/content/audit") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class ReviewAuditExportController {
 private final BookReviewEntryRepository reviews;private final ContentRevisionRepository revisions;
 @GetMapping("/reviews/export") public ResponseEntity<byte[]> reviews(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){var dates=CsvDates.validate(from,to);var result=reviews.findByCreatedAtGreaterThanEqualAndCreatedAtLessThanOrderByCreatedAtDescIdDesc(dates.from().atStartOfDay(),dates.to().plusDays(1).atStartOfDay(),PageRequest.of(0,10000));limit(result.getTotalElements());return csv("review-audit.csv",List.of("Thời gian","Người thao tác","Hành động","Sách","Phân công","Ghi chú"),result.getContent().stream().map(r->Arrays.asList(r.getCreatedAt(),r.getActor(),r.getAction(),r.getBookId(),r.getAssignee(),r.getNote())).toList());}
 @GetMapping("/revisions/export") public ResponseEntity<byte[]> revisions(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){var dates=CsvDates.validate(from,to);var result=revisions.export(dates.from().atStartOfDay(),dates.to().plusDays(1).atStartOfDay(),PageRequest.of(0,10000));limit(result.getTotalElements());return csv("revision-audit.csv",List.of("Thời gian","Người thao tác","Hành động","Loại","Mã nội dung","Sách"),result.getContent().stream().map(r->Arrays.asList(r.getCreatedAt(),r.getActor(),r.getAction(),r.getKind(),r.getResourceId(),r.getBookId())).toList());}
 private void limit(long count){if(count>10000)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Nhật ký vượt 10000 dòng; chọn khoảng ngắn hơn");}
 private ResponseEntity<byte[]> csv(String name,List<String> header,List<? extends List<?>> rows){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+name).contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(SafeCsv.write(header,rows));}
}
